message.content:
{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공동주택 단지 전체의 자발적 금연실천 권장 활동 지원 근거와 조건",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "근거는 서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제9조 제5항이다. 시장은 간접흡연 피해를 예방하기 위하여 금연실천을 권장하는 공동주택에 대해 일정한 표지 등의 설치를 지원할 수 있다. 조건은 ‘금연실천을 권장하는 공동주택’일 것이며, 지원은 재량(할 수 있다)이고 표지 등 설치 지원이라는 점이다. 지원 금액·범위·절차 등 세부 조건은 원문에 없다.",
          "b_ids": "금연:제9조제5항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "금연구역으로 지정된 공용복도 안내표지 경비 지원 근거와 조건",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "근거는 서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제7조 제4항이다. 「주택법」 제2조제3호에 따른 공동주택의 복도, 계단, 엘리베이터 및 지하주차장의 전부 또는 일부가 금연구역으로 지정된 경우, 시장은 예산의 범위에서 안내표지 설치에 필요한 경비의 일부를 지원할 수 있다. 조건은 ① 공동주택의 복도·계단·엘리베이터·지하주차장 전부 또는 일부가 금연구역으로 지정되었을 것, ② 예산의 범위 내일 것, ③ 경비의 ‘일부’ 지원이라는 점이다.",
          "b_ids": "금연:제7조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
